package com.xuyuan.blog.admin.controller.misc;
import com.xuyuan.blog.admin.dto.*;import com.xuyuan.blog.admin.service.AdminScheduleService;import com.xuyuan.blog.admin.vo.schedule.AdminScheduleVO;import com.xuyuan.blog.common.result.*;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.util.*;
@Tag(name="后台日程管理") @RestController @RequestMapping("/xuyuan/admin/schedules") @RequiredArgsConstructor public class AdminScheduleController {private final AdminScheduleService service;@GetMapping @Operation(summary="日程分页列表") public R<PageResult<AdminScheduleVO>> page(ScheduleQueryParam p){return R.ok(service.pageList(p));}@PostMapping @Operation(summary="新增日程") public R<Map<String,Long>> create(@Valid @RequestBody ScheduleCreateParam p){return R.ok(Collections.singletonMap("id",service.create(p)));}@PutMapping("/{id}") @Operation(summary="编辑日程") public R<Void> update(@PathVariable Long id,@Valid @RequestBody ScheduleCreateParam p){service.update(id,p);return R.ok();}@DeleteMapping("/{id}") @Operation(summary="删除日程") public R<Void> delete(@PathVariable Long id){service.delete(id);return R.ok();}}
